def main():
    n = 1600
    seq = [1, 2]
    elements_set = {1, 2}

    while len(seq) < n:
        last = seq[-1]
        T = last + 1
        while True:
            count = 0
            # Check pairs by iterating backwards and stopping when S <= T//2
            for i in reversed(range(len(seq))):
                S = seq[i]
                if S <= T // 2:
                    break
                a = T - S
                if a in elements_set:
                    count += 1
                    if count >= 2:
                        break  # Found multiple pairs, invalid
            if count == 1:
                seq.append(T)
                elements_set.add(T)
                break
            else:
                T += 1

    for idx in range(n):
        diff = seq[idx] - seq[idx-1] if idx > 0 else 0
        print(f"{idx+1} {seq[idx]} {diff}")

