To address the issue of stack overflow in recursive implementations of BST creation for large datasets and to ensure consistency with your request for a C++ implementation, I'm providing the **iterative version in C++**, as originally requested in your previous prompt.

This version avoids deep recursion and is more memory-efficient for large datasets. I've also included the iterative version directly in C++ as requested, rather than providing a Python implementation, to align with your language preference.

---

### ✅ Key Concepts

- **BST Construction from Sorted Array**: The middle element becomes the root, and the left and right halves form the subtrees.
- **Iterative Approach**: Uses a stack to simulate recursion and avoid recursion depth issues.

Each stack element contains:
  - The current subarray's `start` and `end` indices.
  - A reference to the parent node.
  - A flag indicating whether the current node is the **left** or **right** child of the parent.

---

### 🧠 Why This Works

- The recursive approach builds the tree in a **depth-first** manner.
- The iterative version mimics this by using a **stack** to manage the order of node creation.
- To ensure the same structure as the recursive version, we **push the right subtree first**, then the left, so that the left is processed next (LIFO behavior of the stack).

---

### 🧪 Example Code (C++)

```cpp
#include <iostream>
#include <vector>
#include <stack>
using namespace std;

struct Node {
    int data;
    Node* left;
    Node* right;
    Node(int val) : data(val), left(nullptr), right(nullptr) {}
};

typedef tuple<int, int, Node*, bool> StackFrame;

Node* sortedArrayToBSTIterative(vector<int>& arr) {
    if (arr.empty()) return nullptr;

    stack<StackFrame> stack;
    Node* root = nullptr;
    stack.push(make_tuple(0, arr.size() - 1, nullptr, false));

    while (!stack.empty()) {
        auto [start, end, parent, isLeft] = stack.top();
        stack.pop();

        if (start > end) continue;

        int mid = (start + end) / 2;
        Node* node = new Node(arr[mid]);

        if (!parent) {
            root = node;
        } else {
            if (isLeft)
                parent->left = node;
            else
                parent->right = node;
        }

        // Push right first so that left is processed next
        stack.push(make_tuple(mid + 1, end, node, false)); // Right child
        stack.push(make_tuple(start, mid - 1, node, true));  // Left child
    }

    return root;
}

// In-order traversal for verification
void inOrderTraversal(Node* node, vector<int>& result) {
    if (node) {
        inOrderTraversal(node->left, result);
        result.push_back(node.data);
        inOrderTraversal(node->right, result);
    }
}

int main() {
    vector<int> sortedArr = {10, 20, 30, 40, 50, 60, 70};

    cout << "Sorted array: ";
    for (int num : sortedArr) cout << num << " ";
    cout << endl;

    Node* root = sortedArrayToBSTIterative(sortedArr);

    vector<int> inOrder;
    inOrderTraversal(root, inOrder);

    cout << "In-order traversal (iterative): ";
    for (int num : inOrder) cout << num << " ";
    cout << endl;

    return 0;
}
```

