### 🧪 JavaScript Code (Canvas-Based)

```html
<div class="waveform-container">
  <canvas id="waveformCanvas"></canvas>
</div>

<style>
.waveform-container {
  width: 100%;
  height: 32px;
  position: relative;
}

#waveformCanvas {
  width: 100%;
  height: 32px;
  display: block;
}
</style>

<script>
const canvas = document.getElementById('waveformCanvas');
const ctx = canvas.getContext('2d');

// Dynamic resizing
function resizeCanvas() {
  canvas.width = canvas.offsetWidth;
  canvas.height = 32;
}

window.addEventListener('resize', resizeCanvas);
resizeCanvas();

// Waveform parameters
let offset = 0;
const period = 100; // Width of one wave cycle
const pulseDuration = 200; // Duration of dot scaling (ms)
let lastPulseTime = 0;

function drawWaveform(currentTime) {
  // Clear canvas
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Draw baseline
  ctx.beginPath();
  ctx.moveTo(0, 16);
  ctx.lineTo(canvas.width, 16);
  ctx.strokeStyle = '#f00';
  ctx.lineWidth = 1;
  ctx.stroke();

  // Draw triangle waveform
  ctx.beginPath();
  ctx.strokeStyle = '#00ff00';
  ctx.lineWidth = 3;

  for (let x = 0; x < canvas.width; x++) {
    const waveX = x + offset;
    const t = (waveX % period) / period;
    const y = t < 0.5 
      ? 2 * t * 32 
      : 32 - 2 * (t - 0.5) * 32;

    if (x === 0) {
      ctx.moveTo(x, y);
    } else {
      ctx.lineTo(x, y);
    }
  }

  ctx.stroke();

  // Draw moving dot
  const dotX = offset % canvas.width;
  const waveX = dotX + offset;
  const t = (waveX % period) / period;
  const dotY = t < 0.5 
    ? 2 * t * 32 
    : 32 - 2 * (t - 0.5) * 32;

  // Determine if at peak or valley
  const isAtPeak = Math.abs(t - 0.5) < 0.01;
  const isAtValley = Math.abs(t - 0.0) < 0.01 || Math.abs(t - 1.0) < 0.01;

  // Calculate scale factor for dot
  let scale = 1;
  if (isAtPeak || isAtValley) {
    const elapsed = currentTime - lastPulseTime;
    if (elapsed < pulseDuration) {
      const halfDuration = pulseDuration / 2;
      if (elapsed < halfDuration) {
        scale = 1 + (elapsed / halfDuration) * 3; // Scale up
      } else {
        scale = 4 - ((elapsed - halfDuration) / halfDuration) * 3; // Scale down
      }
    } else {
      lastPulseTime = currentTime;
    }
  } else {
    lastPulseTime = currentTime;
  }

  // Draw the dot
  ctx.beginPath();
  ctx.arc(dotX, dotY, 4 * scale, 0, Math.PI * 2);
  ctx.fillStyle = '#000';
  ctx.fill();

  // Update offset for scrolling effect
  offset += 0.3;

  requestAnimationFrame(drawWaveform);
}

// Start animation
requestAnimationFrame(drawWaveform);
</script>
```

