// worker.js
const { fork } = require('child_process');
const { parse } = require('papaparse');
const fs = require('fs');
const path = require('path');
const { pool } = require('./db'); // Assume this is your PostgreSQL pool
const { sendEmail } = require('./mailer'); // Assume this is your email module

// Process for chunking CSV
const chunkCSV = (csvPath, chunkSize = 10000) => {
    return new Promise((resolve, reject) => {
        const chunks = [];
        let currentChunk = [];
        let recordCount = 0;

        fs.createReadStream(csvPath)
            .pipe(csv({ headers: true }))
            .on('data', (row) => {
                currentChunk.push(row);
                recordCount++;

                if (recordCount % chunkSize === 0) {
                    chunks.push([...currentChunk]);
                    currentChunk = [];
                }
            })
            .on('end', () => {
                if (currentChunk.length > 0) {
                    chunks.push(currentChunk);
                }
                resolve(chunks);
            })
            .on('error', (err) => {
                reject(err);
            });
    });
};

// Process chunks in parallel
const processChunks = async (chunks, jobId) => {
    const workers = [];
    const results = [];

    // Send initial progress
    process.send({
        type: 'JOB_PROGRESS',
        jobId,
        progress: 0
    });

    // Create a worker for each chunk
    chunks.forEach((chunk, index) => {
        const worker = fork('chunkProcessor.js');

        worker.send({
            type: 'PROCESS_CHUNK',
            chunkId: `chunk-${index}-${Date.now()}`,
            jobId,
            data: chunk
        });

        // Collect results
        worker.on('message', (msg) => {
            if (msg.type === 'CHUNK_COMPLETE') {
                results.push(msg);

                // Update progress
                const progress = Math.round((results.length / chunks.length) * 100);
                process.send({
                    type: 'JOB_PROGRESS',
                    jobId,
                    progress
                });

                // If all chunks complete, finish job
                if (results.length === chunks.length) {
                    process.send({
                        type: 'JOB_COMPLETE',
                        jobId
                    });
                }
            }
        });

        // Handle worker errors
        worker.on('error', (err) => {
            process.send({
                type: 'JOB_ERROR',
                jobId,
                error: `Chunk worker error: ${err}`
            });
        });

        workers.push(worker);
    });
};

