    ctx.arc(CENTER.x, CENTER.y, planet.orbital_radius * SCALE, 0, Math.PI * 2);
    ctx.stroke();

    // Draw planet
    ctx.beginPath();
    ctx.fillStyle = planet.color;
    ctx.arc(position.x, position.y, Math.max(2, Math.log(planet.radius)), 0, Math.PI * 2);
    ctx.fill();
}

function animate() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw Sun
    ctx.beginPath();
    ctx.fillStyle = '#FFFF00';
    ctx.arc(CENTER.x, CENTER.y, 5, 0, Math.PI * 2);
    ctx.fill();

    // Update and draw planets
    planets.forEach(planet => {
        // Simple circular approximation for demonstration
        const angle = time / (Math.sqrt(planet.semi_major_axis**3)) * 0.01;
        const x = CENTER.x + planet.orbital_radius * Math.cos(angle) * SCALE;
        const y = CENTER.y + planet.orbital_radius * Math.sin(angle) * SCALE;

        drawPlanet(planet, { x, y });
    });

    time += 0.1;
    animationId = requestAnimationFrame(animate);
}

// Start animation
animate();

// Handle accessibility and device input
window.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
        cancelAnimationFrame(animationId);
        ctx.fillStyle = 'white';
        ctx.fillText('Simulation paused. Press R to resume.', 10, 20);
    }
    if (e.key === 'r' || e.key === 'R') {
        animate();
    }
});
```
